// Generated by vibelang from src/theme/discovery.ts; the migrate flow writes it again with each batch.
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
export async function discoverThemes(directories) {
    const result = {};
    for (const directory of directories) {
        const themeDirectory = path.join(directory, "themes");
        const entries = await readdir(themeDirectory, { withFileTypes: true }).catch((error) => {
            if (error && typeof error === "object" && "code" in error && error.code === "ENOENT")
                return [];
            return Promise.reject(error);
        });
        const files = entries
            .filter((entry) => (entry.isFile() || entry.isSymbolicLink()) && path.extname(entry.name) === ".json")
            .map((entry) => path.join(themeDirectory, entry.name))
            .sort();
        for (const file of files) {
            result[path.basename(file, ".json")] = JSON.parse(await readFile(file, "utf8"));
        }
    }
    return result;
}
